	private static String encode(String text) {
		return Base64.getEncoder().encodeToString(text.getBytes(StandardCharsets.UTF_8));
	}

	private static String decode(String text) {
		return new String(Base64.getDecoder().decode(text), StandardCharsets.UTF_8);
	}

	private static Value value(String term) {
		String[] fields = term.split("~", -1);
		switch (fields[0]) {
		case "I":
			return VF.createIRI(decode(fields[1]));
		case "B":
			return VF.createBNode(decode(fields[1]));
		case "L":
			String language = decode(fields[3]);
			if (!language.isEmpty()) {
				return fields[4].isEmpty() ? VF.createLiteral(decode(fields[1]), language)
						: VF.createLiteral(decode(fields[1]), language, Literal.BaseDirection.valueOf(fields[4]));
			}
			return VF.createLiteral(decode(fields[1]), VF.createIRI(decode(fields[2])));
		case "T":
			return VF.createTripleTerm((Resource) value(decode(fields[1])), (IRI) value(decode(fields[2])),
					value(decode(fields[3])));
		default:
			throw new IllegalArgumentException("Unknown term encoding " + fields[0]);
		}
	}

	private static Resource context(String term) {
		return term.equals("N") ? null : (Resource) value(term);
	}

	private static String term(Value value) {
		if (value == null) {
			return "N";
		}
		if (value instanceof IRI) {
			return "I~" + encode(value.stringValue());
		}
		if (value instanceof BNode) {
			return "B~" + encode(((BNode) value).getID());
		}
		if (value instanceof Literal) {
			Literal literal = (Literal) value;
			String direction = literal.getBaseDirection() == null ? "" : literal.getBaseDirection().name();
			// RDF language tag identity is case-insensitive; label/datatype/direction are exact.
			return "L~" + encode(literal.getLabel()) + "~" + encode(literal.getDatatype().stringValue()) + "~"
					+ encode(literal.getLanguage().orElse("").toLowerCase(Locale.ROOT)) + "~" + direction;
		}
		if (value instanceof TripleTerm) {
			TripleTerm triple = (TripleTerm) value;
			return "T~" + encode(term(triple.getSubject())) + "~" + encode(term(triple.getPredicate())) + "~"
					+ encode(term(triple.getObject()));
		}
		throw new IllegalArgumentException("Unsupported value class " + value.getClass());
	}

	private static String row(Statement statement) {
		return String.join("\t", term(statement.getSubject()), term(statement.getPredicate()),
				term(statement.getObject()), term(statement.getContext()));
	}

	private static Map<String, Long> bag(Collection<String> values) {
		Map<String, Long> result = new TreeMap<>();
		for (String value : values) {
			result.merge(value, 1L, Long::sum);
		}
		return result;
	}

	private static List<String> difference(Map<String, Long> expected, Map<String, Long> actual) {
		List<String> difference = new ArrayList<>();
		TreeSet<String> keys = new TreeSet<>(expected.keySet());
		keys.addAll(actual.keySet());
		for (String key : keys) {
			long want = expected.getOrDefault(key, 0L);
			long found = actual.getOrDefault(key, 0L);
			if (want != found) {
				difference.add("expected=" + want + " actual=" + found + "\t" + key);
			}
		}
		return difference;
	}

