	/** Apply the declared persisted-format representation to independent inputs, before MemoryStore evaluates them. */
	private Value expectedValue(Value value) {
		if (format.equals("v2")) {
			return value;
		}
		if (!format.equals("v6")) {
			throw new IllegalArgumentException("Unknown expected format " + format);
		}
		if (value instanceof Literal literal && literal.getLanguage().isPresent()) {
			return VF.createLiteral(literal.getLabel(), literal.getLanguage().orElseThrow().toLowerCase(Locale.ROOT),
					literal.getBaseDirection());
		}
		if (value instanceof TripleTerm triple) {
			return VF.createTripleTerm((Resource) expectedValue(triple.getSubject()),
					(IRI) expectedValue(triple.getPredicate()), expectedValue(triple.getObject()));
		}
		return value;
	}

	private void populateExpected(RepositoryConnection oracle, Path snapshot) throws IOException {
		oracle.begin();
		try (var input = Files.newInputStream(snapshot);
				var decoded = snapshot.toString().endsWith(".gz") ? new GZIPInputStream(input) : input;
				var reader = new BufferedReader(new InputStreamReader(decoded, StandardCharsets.UTF_8))) {
			for (String line : reader.lines().toList()) {
				if (line.isEmpty()) {
					continue;
				}
				String[] fields = line.split("\t", -1);
				if (fields[0].equals("S")) {
					oracle.add((Resource) expectedValue(value(fields[1])), (IRI) expectedValue(value(fields[2])),
							expectedValue(value(fields[3])), (Resource) expectedValue(context(fields[4])));
				} else if (fields[0].equals("NS")) {
					oracle.setNamespace(decode(fields[1]), decode(fields[2]));
				} else {
					throw new IllegalArgumentException("Unknown snapshot record " + fields[0]);
				}
			}
		}
		oracle.commit();
	}

