	private static List<String> query(RepositoryConnection connection, String name, String query) {
		String sparql = PREFIX + query;
		List<String> result = new ArrayList<>();
		if (name.equals("ask")) {
			result.add(Boolean.toString(connection.prepareBooleanQuery(QueryLanguage.SPARQL, sparql).evaluate()));
		} else if (name.equals("construct")) {
			try (var statements = connection.prepareGraphQuery(QueryLanguage.SPARQL, sparql).evaluate()) {
				while (statements.hasNext()) {
					result.add(row(statements.next()));
				}
			}
		} else {
			try (var rows = connection.prepareTupleQuery(QueryLanguage.SPARQL, sparql).evaluate()) {
				while (rows.hasNext()) {
					BindingSet bindings = rows.next();
					List<String> fields = new ArrayList<>();
					for (String binding : new TreeSet<>(bindings.getBindingNames())) {
						fields.add(binding + "=" + term(bindings.getValue(binding)));
					}
					result.add(String.join("\t", fields));
				}
			}
		}
		return result;
	}

